inline fun <T> withLogging(label: String, block: () -> T): T {
    println("Starting $label")
    return block()
}

inline fun runDelayed(crossinline action: () -> Unit) {
    Handler(Looper.getMainLooper()).postDelayed({ action() }, 1000)
}

inline fun setup(immediate: () -> Unit, noinline deferred: () -> Unit): () -> Unit {
    immediate(); return deferred
}

data class Money(val cents: Long) {
    operator fun plus(other: Money) = Money(cents + other.cents)
}

@OptIn(ExperimentalContracts::class)
fun requireValid(user: User?): Boolean {
    contract { returns(true) implies (user != null) }
    return user != null
}

fun describe(x: Any) {
    if (x is String) println(x.length)
}

